// Plain-language explanations of a run, computed only from its events and metrics: one sentence per event for
// the timeline, and findings (bottlenecks, backpressure, hit rates, retries, failures) with the numbers behind
// them. Deterministic; nothing here is generated by a language model.
import type { ComponentKind, ConfigOf, Design } from "./model.ts";
import { fieldsFor } from "./fields.ts";
import { nominalCapacity, type Summary } from "./metrics.ts";
import type { Failure, SimEvent, SimRun } from "./simulate.ts";

export const ms = (value: number | null | undefined) => (value === null || value === undefined ? "–" : `${Math.round(value)} ms`);
export const seconds = (t: number) => `${(t / 1000).toFixed(3)} s`;
export const pct = (value: number) => `${Math.round(value * 100)}%`;

const nameOf = (design: Design) => {
  const labels = new Map(design.nodes.map((n) => [n.id, n.label]));
  return (id: string | undefined) => (id ? labels.get(id) ?? id : "");
};

export function failureText(failure: Failure, design: Design) {
  const name = nameOf(design)(failure.node);
  switch (failure.code) {
    case "down": return `${name} was down and refused it`;
    case "crashed": return `${name} failed while working on it`;
    case "queue-full": return `${name} was full and refused it`;
    case "no-healthy-target": return `${name} had no healthy server to send it to`;
    case "timeout": return "the client stopped waiting (timeout)";
    case "no-origin": return `${name} had nowhere to fetch it from`;
  }
}

const what = (e: SimEvent) => {
  const item = e.key !== undefined ? ` item ${e.key}` : "";
  switch (e.op) {
    case "read": return `read of${item}`;
    case "write": return `write of${item}`;
    case "asset": return `file ${e.key}`;
    case "get": return `lookup of${item}`;
    case "set": return `store of${item}`;
    case "delete": return `removal of${item}`;
    case "publish": return `message for${item}`;
    case "apply": return `replicated write of${item}`;
    default: return "request";
  }
};
const who = (e: SimEvent) => (e.req !== undefined ? `request #${e.req}` : e.msg !== undefined ? `message #${e.msg}` : "");

/** One sentence for one event, as the timeline shows it. */
export function describeEvent(e: SimEvent, design: Design): string {
  const name = nameOf(design);
  const n = name(e.node);
  switch (e.type) {
    case "request": return `${n} sends ${who(e)}: a ${what(e)}.`;
    case "retry": return `${n} tries ${who(e)} again (attempt ${e.attempt}).`;
    case "send": return `${n} → ${name(e.to)}: ${what(e)} for ${who(e)}.`;
    case "queued": return `${n}: every slot is busy, so the ${what(e)} waits (${e.depth} waiting${e.part !== undefined && design.nodes.find((x) => x.id === e.node)?.kind === "nosql" ? ` on partition ${e.part}` : ""}).`;
    case "start": return `${n} starts the ${what(e)}${e.busy !== undefined && design.nodes.find((x) => x.id === e.node)?.kind !== "cache" ? ` (${e.busy} in progress)` : ""}.`;
    case "reject": return `${n} refuses the ${what(e)} for ${who(e)}: ${failureText(e.reason!, design)}.`;
    case "reply": return e.ok ? `${n} answers ${name(e.to)}.` : `${n} answers ${name(e.to)} with an error: ${failureText(e.reason!, design)}.`;
    case "cache": return e.hit ? `${n}: hit, ${e.op === "asset" || design.nodes.find((x) => x.id === e.node)?.kind === "cdn" ? `file ${e.key}` : `item ${e.key}`} is stored here.` : `${n}: miss, ${design.nodes.find((x) => x.id === e.node)?.kind === "cdn" ? `file ${e.key}` : `item ${e.key}`} isn't stored here.`;
    case "complete": return e.ok ? `${who(e)} succeeds after ${ms(e.latency)}${e.status === 202 ? " (accepted for background processing)" : ""}.` : `${who(e)} fails after ${ms(e.latency)}: ${failureText(e.reason!, design)}.`;
    case "timeout": return `${n} stops waiting for ${who(e)} (attempt ${e.attempt}).`;
    case "late": return `An answer to ${who(e)} reaches ${n} after it stopped waiting: that work was wasted.`;
    case "publish": return `${n} stores message #${e.msg} (${e.depth} waiting).`;
    case "consume": return `${n} hands message #${e.msg} to ${name(e.to)} (${e.depth} still waiting).`;
    case "ack": return `${n} finishes message #${e.msg}, ${ms(e.latency)} after it was queued.`;
    case "redeliver": return `${n} couldn't finish message #${e.msg} (${failureText(e.reason!, design)}); it returns to ${name(e.to)} later.`;
    case "requeue": return `Message #${e.msg} is back in ${n} (${e.depth} waiting).`;
    case "dead-letter": return `${n} sets message #${e.msg} aside as a dead letter: it failed too many times.`;
    case "replicate": return `${n} copies the write of item ${e.key} to ${name(e.to)}.`;
    case "applied": return `${n} has applied the replicated write of item ${e.key}.`;
    case "fault": return `${n} fails. Work in progress there is lost.`;
    case "recover": return `${n} is back.`;
    case "health": return e.healthy ? `${n}'s health check finds ${name(e.to)} healthy again.` : `${n}'s health check finds ${name(e.to)} down and stops sending to it.`;
  }
}

/** Events that matter at a glance, for the timeline's "Important only" filter. */
export const isNotable = (e: SimEvent) =>
  e.type === "reject" || e.type === "timeout" || e.type === "late" || e.type === "fault" || e.type === "recover" || e.type === "health" ||
  e.type === "dead-letter" || e.type === "redeliver" || e.type === "retry" || (e.type === "complete" && !e.ok);

/** The settings that set a component's capacity, with this run's values: what to change to move the limit. */
const limitFields: Partial<Record<ComponentKind, string[]>> = { api: ["concurrency", "serviceMs"], sql: ["concurrency", "readMs", "writeMs"], nosql: ["partitions", "concurrencyPerPartition", "opMs"], worker: ["concurrency", "serviceMs"] };
export function limitSettings(node: Design["nodes"][number]) {
  return (limitFields[node.kind] ?? [])
    .map((name) => fieldsFor[node.kind].find((f) => f.field === name)!)
    .map((f) => `${f.label} ${(node.config as Record<string, number>)[f.field]}${f.type === "number" && f.unit ? ` ${f.unit}` : ""}`)
    .join(", ");
}

export type Finding = { id: string; tone: "problem" | "warning" | "good" | "info"; title: string; detail: string; nodes: string[] };

/** What the run shows, most important first. Every number comes from the summary. */
export function findings(run: SimRun, s: Summary): Finding[] {
  const design = run.design;
  const name = nameOf(design);
  const out: Finding[] = [];
  const failedPart = s.requests ? s.failed / s.requests : 0;

  out.push({
    id: "overall",
    tone: failedPart > 0.01 ? "problem" : s.unfinished ? "warning" : "good",
    title: `${pct(s.successRate)} of ${s.requests.toLocaleString("en")} requests succeeded`,
    detail: `Half finished within ${ms(s.p50)}, 95% within ${ms(s.p95)} and 99% within ${ms(s.p99)} (successful requests, measured at the client, retries included).${s.failed ? ` ${s.failed.toLocaleString("en")} failed.` : ""}`,
    nodes: [],
  });

  // Bottlenecks: components whose slots were nearly always in use.
  const busy = design.nodes
    .map((node) => ({ node, util: s.nodes[node.id].utilisation }))
    .filter((x): x is { node: (typeof design.nodes)[number]; util: number[] } => x.util !== null)
    .map((x) => ({ ...x, peak: Math.max(...x.util), mean: x.util.reduce((a, b) => a + b, 0) / x.util.length }))
    .sort((a, b) => b.peak - a.peak);
  for (const { node, util, peak, mean } of busy.filter((x) => x.peak >= 0.85)) {
    const refused = s.nodes[node.id].rejected["queue-full"] ?? 0;
    const capacity = nominalCapacity(design, node.id).map((c) => `about ${c.perSecond.toLocaleString("en")} ${c.what}/s`).join(", ");
    if (node.kind === "nosql" && util.length > 1 && peak > mean * 1.5) {
      out.push({
        id: `hot-${node.id}`,
        tone: "problem",
        title: `${node.label}: one partition is overloaded`,
        detail: `Its busiest partition was in use ${pct(peak)} of the time, the average ${pct(mean)}. Each key always goes to the same partition, so popular keys concentrate load on one of them; adding partitions doesn't split a single hot key.`,
        nodes: [node.id],
      });
      continue;
    }
    out.push({
      id: `bottleneck-${node.id}`,
      tone: "problem",
      title: `${node.label} is a bottleneck`,
      detail: `Its slots were in use ${pct(peak)} of the time. From its settings (${limitSettings(node)}) it can finish ${capacity}.${node.kind === "api" ? " A slot also stays busy while the server waits for the cache or database, so the real figure is lower." : ""}${s.nodes[node.id].maxWaiting ? ` Up to ${s.nodes[node.id].maxWaiting} requests waited for a slot.` : ""}${refused ? ` Its waiting queue filled and it refused ${refused.toLocaleString("en")} requests: backpressure that protects it, at the cost of errors.` : ""}`,
      nodes: [node.id],
    });
  }
  if (!busy.some((x) => x.peak >= 0.85) && busy.length) {
    const top = busy[0];
    out.push({ id: "headroom", tone: "good", title: "No component reached its limit", detail: `The busiest was ${top.node.label}, in use ${pct(top.peak)} of the time.`, nodes: [top.node.id] });
  }

  for (const node of design.nodes.filter((n) => n.kind === "cache" || n.kind === "cdn")) {
    const rate = s.nodes[node.id].hitRate;
    if (rate === null) continue;
    const c = node.config as ConfigOf<"cache">;
    const pool = node.kind === "cdn" ? design.workload.assets : design.workload.keys;
    out.push({
      id: `hits-${node.id}`,
      tone: rate >= 0.6 ? "good" : rate >= 0.3 ? "info" : "warning",
      title: `${node.label} answered ${pct(rate)} of lookups`,
      detail: `It can hold ${c.capacityKeys.toLocaleString("en")} of ${pool.toLocaleString("en")} ${node.kind === "cdn" ? "files" : "items"}, and ${design.workload.skew === "popular" ? "a few popular items get most requests" : "every item is equally likely"}.${node.kind === "cache" ? " It starts empty, so the first reads of each item miss, and every write removes the item." : " It starts empty; each miss is fetched from its origin."}${rate < 0.3 ? " Few hits means most requests still reach what's behind it." : ""}`,
      nodes: [node.id],
    });
  }

  if (s.timeouts) {
    out.push({
      id: "timeouts",
      tone: "problem",
      title: `${s.timeouts.toLocaleString("en")} attempts timed out`,
      detail: `Clients stopped waiting${s.late ? `, and ${s.late.toLocaleString("en")} answers arrived afterwards: the servers did that work for nobody` : ""}. Timeouts usually mean requests are waiting in a queue somewhere.`,
      nodes: design.nodes.filter((n) => n.kind === "client").map((n) => n.id),
    });
  }
  if (s.retries) {
    out.push({
      id: "retries",
      tone: s.retries > s.requests * 0.2 ? "warning" : "info",
      title: `Retries added ${s.retries.toLocaleString("en")} attempts (${pct(s.retries / Math.max(1, s.requests))} more traffic)`,
      detail: "A retry can turn a brief failure into a success, but every retry is another request. When a component is overloaded, retries add load exactly where it hurts; backoff spreads them out.",
      nodes: design.nodes.filter((n) => n.kind === "client").map((n) => n.id),
    });
  }

  for (const fault of design.faults) {
    const failedInside = run.events.filter((e) => e.type === "complete" && !e.ok && e.t >= fault.fromS * 1000 && e.t <= fault.toS * 1000 + 1000).length;
    const lbs = design.edges.filter((e) => e.to === fault.node && design.nodes.find((n) => n.id === e.from)?.kind === "load-balancer").map((e) => design.nodes.find((n) => n.id === e.from)!);
    const unchecked = lbs.filter((lb) => !(lb.config as ConfigOf<"load-balancer">).healthChecks);
    out.push({
      id: `fault-${fault.node}-${fault.fromS}`,
      tone: failedInside ? "problem" : "good",
      title: `${name(fault.node)} failed from ${fault.fromS} s to ${fault.toS} s`,
      detail: failedInside
        ? `${failedInside.toLocaleString("en")} requests failed during the outage.${unchecked.length ? ` ${unchecked.map((lb) => lb.label).join(", ")} had no health checks, so it kept sending requests to the failed server.` : lbs.length ? " The load balancer stopped using it after its next health check; requests sent before then failed." : ""}`
        : "No request failed: the rest of the design covered for it.",
      nodes: [fault.node],
    });
  }

  for (const node of design.nodes.filter((n) => n.kind === "queue")) {
    const q = s.nodes[node.id];
    if (!q.published) continue;
    const workers = design.edges.filter((e) => e.from === node.id).map((e) => e.to);
    const dead = q.deadLetters;
    out.push({
      id: `queue-${node.id}`,
      tone: q.depth || dead ? "warning" : "info",
      title: `${node.label}: ${q.published.toLocaleString("en")} messages, up to ${q.maxDepth.toLocaleString("en")} waiting`,
      detail: `${q.acked ? "" : "No message was finished. "}95% of finished messages were done within ${ms(workerAckP95(s, workers))} of being queued.${q.depth ? ` ${q.depth.toLocaleString("en")} were still waiting when the run ended: the workers are slower than the messages arrive.` : ""}${dead ? ` ${dead} failed too often and were set aside as dead letters.` : ""}`,
      nodes: [node.id, ...workers],
    });
  }

  if (s.unfinished) out.push({ id: "unfinished", tone: "warning", title: `${s.unfinished.toLocaleString("en")} requests never finished`, detail: "They were still in progress when the run stopped, 30 seconds after the last arrival.", nodes: [] });
  if (s.truncated) out.push({ id: "truncated", tone: "warning", title: "The run was cut short", detail: "It reached the simulator's event limit. Lower the request rate or duration for a complete run.", nodes: [] });
  return out;
}

function workerAckP95(s: Summary, workers: string[]) {
  const values = workers.map((w) => s.nodes[w]?.ackP95).filter((v): v is number => v !== null && v !== undefined);
  return values.length ? Math.max(...values) : null;
}
